def vr_total_nuclei (n_seg : Nat) : Nat := 2 * n_seg
def v_unit_c_axis (cz : Int) : Vec3Int := { x := 0, y := 0, z := cz }
def r_unit_c_axis (rx ry : Int) : Vec3Int := { x := rx, y := ry, z := 0 }
theorem vr_crystal_ring_parity_and_orthogonal_c_axes :
    vr_total_nuclei 32 = 64 ∧ (vr_total_nuclei 32) % 2 = 0 ∧
    vec3_dot (v_unit_c_axis 1) (r_unit_c_axis 3 4) = 0 := by decide

def coccosphere_vertices (f_cocc : Int) : Int := 2 * (f_cocc - 2)
def coccosphere_edges (f_cocc : Int) : Int := 3 * (f_cocc - 2)
def coccosphere_euler_characteristic (f_cocc : Int) : Int :=
  coccosphere_vertices f_cocc - coccosphere_edges f_cocc + f_cocc
theorem coccosphere_euler_polyhedral_packing_and_trivalent_interlock :
    coccosphere_euler_characteristic 16 = 2 ∧
    3 * coccosphere_vertices 16 = 2 * coccosphere_edges 16 ∧
    coccosphere_edges 16 = 42 := by decide

def residual_mpsm_radius_step (M alpha R_n : Int) : Int :=
  (M - alpha) * R_n
def budded_segment_step (alpha R_n : Int) : Int :=
  alpha * R_n
theorem lauschke_2013_geometric_residual_radius_conservation (M alpha R_n : Int) :
    residual_mpsm_radius_step M alpha R_n + budded_segment_step alpha R_n = M * R_n

def manukyan_ca_step (s n_g : Nat) : Nat :=
  if s = 1 then (if 2 ≤ n_g ∧ n_g ≤ 3 then 1 else 0)
  else (if n_g ≤ 1 then 1 else 0)
theorem manukyan_outer_totalistic_ca_labyrinth_fixed_point :
    manukyan_ca_step 1 3 = 1 ∧ manukyan_ca_step 0 3 = 0 ∧
    manukyan_ca_step 1 5 = 0 ∧ manukyan_ca_step 0 1 = 1 := by decide

def switch_S_to_L (d θ : Int) : Bool := decide (d > θ)
def switch_L_to_S (d θ : Int) : Bool := decide (-d > θ)
theorem iridophore_switch_exclusive_and_conservative (d θ s l a b : Int) (hθ : θ ≥ 0) :
    ¬ (switch_S_to_L d θ = true ∧ switch_L_to_S d θ = true) ∧
    (s - a + b) + (l + a - b) = s + l

def contact_inhibited_traction_num (tau n : Nat) : Nat := tau * (n * n)
def contact_inhibited_traction_den (lam n : Nat) : Nat := 1 + lam * (n * n)
theorem oster_murray_1985_contact_inhibited_traction_bound (tau lam n : Nat) :
    lam * contact_inhibited_traction_num tau n ≤
      tau * contact_inhibited_traction_den lam n

def hexagonal_triad_sum_x (k : Int) : Int := (2 * k) + (-k) + (-k)
def hexagonal_triad_sum_y (m : Int) : Int := 0 + m + (-m)
def hexagonal_cubic_gain (alpha3 A : Nat) : Nat := alpha3 * (A * A * A)
theorem hexagonal_villi_triad_closure (k m : Int) (a3 amp : Nat) :
    hexagonal_triad_sum_x k = 0 ∧
    hexagonal_triad_sum_y m = 0 ∧
    hexagonal_cubic_gain (a3 + 1) (amp + 1) > 0

def zoelly_pressure_scaled (c_e h : Nat) : Nat :=
  c_e * (h * h)
def zoelly_radius_doubling_lhs (c_e r : Nat) : Nat :=
  c_e * ((2 * r) * (2 * r))
def zoelly_radius_doubling_rhs (c_e r : Nat) : Nat :=
  4 * (c_e * (r * r))
theorem zoelly_quadratic_shell_buckling_scaling (c_e h r : Nat) :
    zoelly_pressure_scaled c_e (2 * h) = 4 * zoelly_pressure_scaled c_e h ∧
    zoelly_radius_doubling_lhs c_e r = zoelly_radius_doubling_rhs c_e r ∧
    zoelly_pressure_scaled 1 2 = 4 * zoelly_pressure_scaled 1 1

def inverted_cap_bending_penalty (hm c0 : Int) : Int := (hm + c0) * (hm + c0)
def aligned_cap_bending_penalty (hm c0 : Int) : Int := (hm - c0) * (hm - c0)
def capsule_wall_winkler_penalty (r R : Int) : Int :=
  if r ≤ R then 0 else (r - R) * (r - R)
theorem inverted_cap_penalty_and_capsule_wall_contact
    (hm c0 r R : Int) (hh : 0 ≤ hm) (hc : 0 ≤ c0) :
    inverted_cap_bending_penalty hm c0 = aligned_cap_bending_penalty hm c0 + 4 * (hm * c0) ∧
    aligned_cap_bending_penalty hm c0 ≤ inverted_cap_bending_penalty hm c0 ∧
    (r ≤ R → capsule_wall_winkler_penalty r R = 0) ∧
    (R < r → capsule_wall_winkler_penalty r R > 0)

def rule30 (p q r : Bool) : Bool := bne p (q || r)
def rule30_anf (p q r : Bool) : Bool := bne (bne p q) (bne r (q && r))
theorem rule30_anf_equiv (p q r : Bool) : rule30 p q r = rule30_anf p q r := by
  cases p <;> cases q <;> cases r <;> rfl

def ruliobio_total_triples (k : Nat) : Nat := k * k * k
def ruliobio_sym_orbits (k : Nat) : Nat := k * (k * (k + 1) / 2)
def ruliobio_active_mutations (n_active k : Nat) : Nat := n_active * (k - 1)
def ruliobio_neutral_genotypes (k n_active s_used : Nat) : Nat := k ^ (n_active - s_used)
theorem wolfram_2026_ruliobiology_symmetry_orbits_and_neutral_space :
    ruliobio_total_triples 5 = 125 ∧ ruliobio_sym_orbits 5 = 75 ∧
    ruliobio_active_mutations 74 5 = 296 ∧ ruliobio_total_triples 3 - 1 = 26 ∧
    ruliobio_active_mutations 26 3 = 52 ∧ ruliobio_neutral_genotypes 3 26 18 = 6561 ∧
    125 - 58 = 67 := by decide

def cell_length_buckling_product_residual (L sigma_c L0 sigma_c0 : Int) : Int :=
  L * sigma_c - L0 * sigma_c0
theorem cell_length_inverse_buckling_and_cephalexin_expansion
    (k L L0 : Int) (rc_long_sq delta_rc_sq extra_R_sq : Nat) :
    let rc_short_sq := rc_long_sq + (delta_rc_sq + 1)
    let R_sq := rc_short_sq + (extra_R_sq + 1)
    cell_length_buckling_product_residual L (k * L0) L0 (k * L) = 0 ∧
    verticalization_front_sq R_sq rc_short_sq < verticalization_front_sq R_sq rc_long_sq
